// The betting math, ported from src/betting.py and src/auto_bet.py.
// betting.test.ts checks every function against vectors generated by the
// Python code (scripts/gen_math_vectors.py), so the two can't drift apart.

export const MIN_CONFIDENCE = 0.6;
export const MIN_EDGE = 0.03; // model probability must beat the implied probability by this much
export const MAX_FAVORITE = -250; // prices shorter than this are never bet
export const TOO_GOOD_EDGE = 0.08; // an edge this large usually means the market knows something
export const AUTO_STAKE = 10;

/** Break-even win probability of American odds, vig included. -150 -> 0.600; +130 -> 0.435. */
export function impliedProb(american: number): number {
  return american < 0 ? -american / (-american + 100) : 100 / (american + 100);
}

/** Odds whose implied probability is `prob`, rounded toward the bettor so the
 *  result never implies more than `prob`. 0.60 -> -150; 0.40 -> +150. */
export function toAmerican(prob: number): number {
  const raw = prob >= 0.5 ? (-prob / (1 - prob)) * 100 : ((1 - prob) / prob) * 100;
  // Round to 6 places first so float noise (-149.9999999) can't shift the result.
  return Math.ceil(Number(raw.toFixed(6))) + 0; // + 0 turns -0 into 0
}

/** Profit on a winning bet (stake not included). */
export function payout(american: number, stake: number): number {
  return stake * (american > 0 ? american / 100 : 100 / -american);
}

/** Expected profit per $1 staked, by the model's own probability. */
export function expectedValue(prob: number, american: number): number {
  return prob * payout(american, 1) - (1 - prob);
}

/** The worst odds still worth taking: the model's probability minus the margin, as a price. */
export function limitOdds(prob: number): number {
  return toAmerican(prob - MIN_EDGE);
}

export function isValidAmerican(odds: number): boolean {
  return Number.isInteger(odds) && (odds <= -100 || odds >= 100);
}

export type VerdictKind = "fair" | "too_short" | "negative_ev" | "below_margin" | "too_good";

export interface Verdict {
  kind: VerdictKind;
  implied: number;
  edge: number;
  ev: number;
  fair: number;
  limit: number | null; // null when the probability is too low to have a limit
  /** True when the pick is under the 60% bar the automatic rule needs. */
  underConfidence: boolean;
}

/** Same checks, in the same order, as the automatic bets in src/auto_bet.py. */
export function checkPrice(prob: number, odds: number): Verdict {
  const implied = impliedProb(odds);
  const edge = prob - implied;
  const ev = expectedValue(prob, odds);
  let kind: VerdictKind = "fair";
  if (odds < MAX_FAVORITE) kind = "too_short";
  else if (implied > prob - MIN_EDGE) kind = ev < 0 ? "negative_ev" : "below_margin";
  else if (edge >= TOO_GOOD_EDGE) kind = "too_good";
  return {
    kind,
    implied,
    edge,
    ev,
    fair: toAmerican(prob),
    limit: prob - MIN_EDGE > 0.005 ? limitOdds(prob) : null,
    underConfidence: prob < MIN_CONFIDENCE,
  };
}

/** Parse what a visitor types: "-150", "+130", "130", "−150". Returns null if it isn't a price. */
export function parseAmerican(text: string): number | null {
  const s = text.trim().replace(/−/g, "-").replace(/\s+/g, "");
  if (!/^[+-]?\d{3,5}$/.test(s)) return null;
  const n = Number(s);
  return isValidAmerican(n) ? n : null;
}
